// Generates the per-language data modules from /data, the single source of truth.
// Run with --check in CI to fail when generated files are stale.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");

const read = (name) => JSON.parse(readFileSync(join(root, "data", name), "utf8"));
const governorates = read("governorates.json");
const prefixes = read("mobile-prefixes.json");

const header = "// Generated by scripts/sync-data.mjs from /data. Do not edit by hand.\n\n";

const outputs = {
  "js/src/generated/data.ts":
    header +
    `export const GOVERNORATE_DATA = ${JSON.stringify(governorates, null, 2)} as const;\n\n` +
    `export const MOBILE_PREFIX_DATA = ${JSON.stringify(prefixes, null, 2)} as const;\n`,
  "python/src/wasta/_data/governorates.json": JSON.stringify(governorates, null, 2) + "\n",
  "python/src/wasta/_data/mobile-prefixes.json": JSON.stringify(prefixes, null, 2) + "\n",
};

let stale = [];
for (const [file, content] of Object.entries(outputs)) {
  const path = join(root, file);
  let current = null;
  try {
    current = readFileSync(path, "utf8");
  } catch {}
  if (current === content) continue;
  if (check) {
    stale.push(relative(root, path));
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`wrote ${file}`);
  }
}

if (stale.length) {
  console.error(`Generated data is out of date:\n  ${stale.join("\n  ")}\nRun: node scripts/sync-data.mjs`);
  process.exit(1);
}
